UIRoundTitleGroup=function(game,gameController){Phaser.Group.call(this,game,null);this.gameController=gameController;this.title=this.addChild(new Phaser.Text(game,0,-UIConstants.ROUND_TITLE_SPACING/2.0,'',{font:UIConstants.ROUND_TITLE_FONT_SIZE+"px TankTrouble",fontWeight:"bold",fill:"#ffffff",stroke:"#000000",strokeThickness:UIConstants.ROUND_TITLE_STROKE_WIDTH}));this.title.anchor.setTo(0.5,0.5);this.title.kill();this.subtitle=this.addChild(new Phaser.Text(game,0,UIConstants.ROUND_TITLE_SPACING/2.0,'',{font:UIConstants.ROUND_RANKED_FONT_SIZE+"px TankTrouble",fontWeight:"bold",fill:"#e00000",stroke:"#000000",strokeThickness:UIConstants.ROUND_TITLE_STROKE_WIDTH}));this.subtitle.anchor.setTo(0.5,0.5);this.subtitle.kill();this.exists=false;this.visible=false;};UIRoundTitleGroup.prototype=Object.create(Phaser.Group.prototype);UIRoundTitleGroup.prototype.constructor=UIRoundTitleGroup;UIRoundTitleGroup.prototype.update=function(){if(!this.exists){return;}Phaser.Group.prototype.update.call(this);};UIRoundTitleGroup.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Group.prototype.postUpdate.call(this);};UIRoundTitleGroup.prototype.spawn=function(title,subtitle){this.exists=true;this.visible=true;this.title.revive();this.title.text=title;this.title.scale.set(0.0,0.0);if(subtitle!=""){this.subtitle.revive();this.subtitle.text=subtitle;this.subtitle.scale.set(0.0,0.0);}else{this.subtitle.kill();}this.removeEvent=this.game.time.events.add(UIConstants.ROUND_TITLE_DISPLAY_TIME,this.remove,this);this.game.add.tween(this.title.scale).to({x:1.0,y:1.0},300,Phaser.Easing.Back.Out,true);if(subtitle!=""){this.game.add.tween(this.subtitle.scale).to({x:1.0,y:1.0},300,Phaser.Easing.Back.Out,true);}};UIRoundTitleGroup.prototype.remove=function(){this.removeEvent=null;this.game.add.tween(this.title.scale).to({x:0.0,y:0.0},100,Phaser.Easing.Linear.None,true).onComplete.add(function(){this.kill();this.exists=false;this.visible=false;},this.title);this.game.add.tween(this.subtitle.scale).to({x:0.0,y:0.0},100,Phaser.Easing.Linear.None,true).onComplete.add(function(){this.kill();},this.subtitle);};UIRoundTitleGroup.prototype.retire=function(){if(this.removeEvent){this.game.time.events.remove(this.removeEvent);}this.title.kill();this.subtitle.kill();this.exists=false;this.visible=false;};